package com.campus.lostfound.config;import org.springframework.beans.factory.annotation.Value;import org.springframework.context.annotation.Configuration;import org.springframework.web.servlet.config.annotation.*;import java.nio.file.Path;@Configuration public class WebConfig implements WebMvcConfigurer{@Value("${app.upload-dir:uploads}")String dir;public void addResourceHandlers(ResourceHandlerRegistry r){r.addResourceHandler("/uploads/**").addResourceLocations(Path.of(dir).toAbsolutePath().toUri().toString());}}
